<?php
require_once __DIR__.'/config/database.php';
$rooms=$pdo->query("SELECT * FROM rooms WHERE status='available' ORDER BY price")->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();$roomId=(int)($_POST['room_id']??0);$checkIn=$_POST['check_in']??'';$checkOut=$_POST['check_out']??'';$guests=(int)($_POST['guests']??0);$name=trim($_POST['guest_name']??'');$email=trim($_POST['guest_email']??'');$phone=trim($_POST['guest_phone']??'');$special=trim($_POST['special_requests']??'');
 $q=$pdo->prepare("SELECT * FROM rooms WHERE room_id=? AND status='available'");$q->execute([$roomId]);$room=$q->fetch();$start=DateTime::createFromFormat('Y-m-d',$checkIn);$end=DateTime::createFromFormat('Y-m-d',$checkOut);$nights=($start&&$end)?(int)$start->diff($end)->format('%r%a'):0;
 if(!$room||!$start||!$end||$nights<1||$checkIn<date('Y-m-d')||$guests<1||$guests>(int)($room['capacity']??0)||!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^[+0-9 ()-]{7,20}$/',$phone)||strlen($special)>1000){$error='Please check your details. Select valid dates, a suitable guest count, and a valid email and phone number.';}
 else{$q=$pdo->prepare("SELECT COUNT(*) FROM bookings WHERE room_id=? AND status IN ('pending','confirmed') AND check_in < ? AND check_out > ?");$q->execute([$roomId,$checkOut,$checkIn]);if((int)$q->fetchColumn()>0){$error='This room is already reserved for part of those dates. Please choose another room or date.';}else{$ref='LM-'.strtoupper(bin2hex(random_bytes(4)));$q=$pdo->prepare('INSERT INTO bookings (booking_reference,user_id,room_id,guest_name,guest_email,guest_phone,check_in,check_out,guests,total_amount,special_requests,status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$ref,current_user()['user_id']??null,$roomId,$name,$email,$phone,$checkIn,$checkOut,$guests,$nights*(float)$room['price'],$special,'pending']);$_SESSION['confirmed_booking']=['reference'=>$ref,'room'=>$room['room_name'],'nights'=>$nights,'amount'=>$nights*(float)$room['price']];redirect('booking.php?confirmed=1');}}
}
$selected=(int)($_GET['room_id']??$_POST['room_id']??0);$pageTitle='Reserve your stay | LUMIÈRE';require __DIR__.'/includes/header.php';
?>
<section class="page-hero"><div><div class="eyebrow">The beginning of something lovely</div><h1>Reserve your stay</h1></div></section><section class="content-wrap"><div class="split"><div><div class="eyebrow">A little anticipation</div><h2 style="font:40px var(--serif);font-weight:400;color:var(--navy)">We look forward to welcoming you.</h2><p>Tell us when you would like to arrive. Your reservation will be held as pending while our team prepares to confirm the details.</p><p>For a hand with your plans, call <strong>+91 413 555 0142</strong>.</p></div><div class="panel"><?php if(isset($_GET['confirmed'])&&isset($_SESSION['confirmed_booking'])):$b=$_SESSION['confirmed_booking'];unset($_SESSION['confirmed_booking']);?><div class="center-message" style="padding:20px"><div class="eyebrow">A reservation received</div><h2>Thank you. It’s a date.</h2><p>Your reference is <strong><?= e($b['reference']) ?></strong>.</p><p><?= e($b['room']) ?> · <?= (int)$b['nights'] ?> nights · ₹<?= number_format((float)$b['amount']) ?></p><p>We have sent this request to our team. You can view it in My Stays after signing in.</p><a class="button" href="index.php">Return home</a></div><?php else: ?><h2>Your stay, your way.</h2><?php if($error): ?><div class="toast-error" style="padding:12px;color:#8a4035;background:#f7e9e5;margin-bottom:15px"><?= e($error) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="form-grid"><div class="form-field wide"><label>Your name</label><input name="guest_name" value="<?= e(current_user()['name']??($_POST['guest_name']??'')) ?>" required maxlength="120"></div><div class="form-field"><label>Email</label><input type="email" name="guest_email" value="<?= e(current_user()['email']??($_POST['guest_email']??'')) ?>" required></div><div class="form-field"><label>Phone</label><input name="guest_phone" value="<?= e(current_user()['phone']??($_POST['guest_phone']??'')) ?>" required></div><div class="form-field"><label>Room</label><select name="room_id" required><option value="">Select a room</option><?php foreach($rooms as $r): ?><option value="<?= (int)$r['room_id'] ?>" <?= $selected===(int)$r['room_id']?'selected':'' ?>><?= e($r['room_name']) ?> · ₹<?= number_format((float)$r['price']) ?>/night</option><?php endforeach; ?></select></div><div class="form-field"><label>Guests</label><select name="guests"><?php for($i=1;$i<=6;$i++): ?><option <?= (($_POST['guests']??'2')==$i)?'selected':'' ?>><?= $i ?></option><?php endfor; ?></select></div><div class="form-field"><label>Arrival</label><input type="date" name="check_in" value="<?= e($_POST['check_in']??$_GET['check_in']??'') ?>" required></div><div class="form-field"><label>Departure</label><input type="date" name="check_out" value="<?= e($_POST['check_out']??$_GET['check_out']??'') ?>" required></div><div class="form-field wide"><label>Anything we should know?</label><textarea name="special_requests" maxlength="1000"><?= e($_POST['special_requests']??'') ?></textarea></div></div><button class="button">Request your reservation</button></form><?php endif; ?></div></div></section><?php require __DIR__.'/includes/footer.php'; ?>
